// Responsive images generated by `npm run images` (scripts/optimize-images.mjs).
// An image is referenced by its base path, e.g. '/images/projects/tennis-court/01-home',
// and exists on disk as `<base>-480.webp`, `<base>-720.webp`, `<base>-960.webp` and `<base>-1600.webp`.

export const IMAGE_WIDTHS = [480, 720, 960, 1600] as const;
type Width = (typeof IMAGE_WIDTHS)[number];

export const imgSrc = (base: string, width: Width = 960) => `${base}-${width}.webp`;

export const imgSrcSet = (base: string) => IMAGE_WIDTHS.map((w) => `${imgSrc(base, w)} ${w}w`).join(', ');

/** Warm the browser cache for an image (e.g. the next gallery slide). */
export const preloadImage = (base: string, sizes: string) => {
  const img = new Image();
  img.sizes = sizes;
  img.srcset = imgSrcSet(base);
  img.src = imgSrc(base);
};
